const input = $input.first().json;

const clientName = input.client_name || '';
const batchDate = input.batch_date || DateTime.now().toFormat('yyyy-MM-dd');
const fetchLatest = input.fetch_latest_call_transcript === true || input.fetch_latest_call_transcript === 'true';
const notesRaw = (input.notes_for_ai || '').trim();

// Detect specific past call reference in notes
let specificCallRef = null;
const callNumMatch = notesRaw.match(/(?:use|from|based on|refer to)\s+call\s+(?:#|number\s+)?(\d+)/i);
const dateMatch = notesRaw.match(/(?:use|from|based on|refer to).*?(?:call|transcript).*?\b((?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s+\d{1,2}(?:st|nd|rd|th)?,?\s*(?:\d{4})?)/i);

if (callNumMatch) {
  specificCallRef = { type: 'call_number', value: callNumMatch[1] };
} else if (dateMatch) {
  specificCallRef = { type: 'date', value: dateMatch[1] };
}

// Derive call sign from client name — initials of capitalised words, strip parentheticals
const cleanName = clientName.replace(/\s*\(.*?\)\s*/g, '').trim();
const callSign = cleanName
  .split(/\s+/)
  .filter(w => /^[A-Z]/.test(w))
  .map(w => w[0])
  .join('');

return [{
  json: {
    client_name: clientName,
    batch_date: batchDate,
    fetch_latest_transcript: fetchLatest,
    notes_for_ai: notesRaw,
    specific_call_ref: specificCallRef,
    has_specific_call_override: specificCallRef !== null,
    call_sign: callSign
  }
}];

const notionResult = $input.first().json;
const preprocess = $('Pre-process Inputs').first().json;

if (!notionResult.results || notionResult.results.length === 0) {
  throw new Error(`No client dashboard found for: ${preprocess.client_name}`);
}

const dashboard = notionResult.results[0];
const dashboardId = dashboard.id;

// Extract emails from dashboard properties
const props = dashboard.properties || {};
const primaryEmail = props['Primary Email']?.email || props['Primary Email']?.rich_text?.[0]?.plain_text || '';
const secondaryEmail = props['Secondary Email']?.email || props['Secondary Email']?.rich_text?.[0]?.plain_text || '';

return [{
  json: {
    ...preprocess,
    dashboard_page_id: dashboardId,
    primary_email: primaryEmail,
    secondary_email: secondaryEmail
  }
}];

const dashboardInfo = $('Extract Dashboard Info').first().json;
const dashboardId = dashboardInfo.dashboard_page_id;

// Find Intelligence Brief — prefer the one whose parent is client dashboard
const intelResults = $('Find Intelligence Brief Page').first().json?.results || [];
const intelPage = intelResults.find(p => p.parent?.page_id === dashboardId)
  || intelResults.find(p => p.object === 'page') || null;

// Find Content Strategy Doc — prefer parent match
const strategyResults = $('Find Content Strategy Doc Page').first().json?.results || [];
const strategyPage = strategyResults.find(p => p.parent?.page_id === dashboardId)
  || strategyResults.find(p => p.object === 'page') || null;

if (!intelPage) throw new Error('Intelligence Brief page not found for client: ' + dashboardInfo.client_name);
if (!strategyPage) throw new Error('Content Strategy Doc page not found for client: ' + dashboardInfo.client_name);

return [{
  json: {
    ...dashboardInfo,
    intel_brief_page_id: intelPage.id,
    strategy_doc_page_id: strategyPage.id
  }
}];

// Helper: extract plain text from Notion blocks
function blocksToText(blocks) {
  return (blocks || []).map(block => {
    const type = block.type;
    const content = block[type];
    if (!content) return '';
    const richText = content.rich_text || content.text || [];
    return richText.map(t => t.plain_text || '').join('');
  }).filter(Boolean).join('\n');
}

const dashboardInfo = $('Resolve Page IDs').first().json;
const intelBlocks = $('Fetch Intelligence Brief').first().json?.results || [];
const strategyBlocks = $('Fetch Content Strategy Doc').first().json?.results || [];

const intelBriefText = blocksToText(intelBlocks);
const strategyDocText = blocksToText(strategyBlocks);

// Parse posting cadence from strategy doc
// Look for patterns like "14 posts/week", "LinkedIn: 7, X: 7", etc.
const totalPostsMatch = strategyDocText.match(/(\d+)\s*(?:posts?|per\s+week|week)/i);
const totalPostsPerBatch = totalPostsMatch ? parseInt(totalPostsMatch[1]) : 14;

// Parse platform split
const linkedinMatch = strategyDocText.match(/linkedin[:\s]+([0-9]+)/i);
const xMatch = strategyDocText.match(/(?:x|twitter)[:\s]+([0-9]+)/i);
const linkedinPosts = linkedinMatch ? parseInt(linkedinMatch[1]) : Math.floor(totalPostsPerBatch / 2);
const xPosts = xMatch ? parseInt(xMatch[1]) : totalPostsPerBatch - linkedinPosts;

// Active sources come from orchestrator input — for this workflow, we're the call transcript source
// Transcript weighting: majority (~65% of base before buffer)
const transcriptBaseShare = Math.ceil(totalPostsPerBatch * 0.65);
// Add +3 buffer (only if we have enough material — enforced by AI, not here)
const transcriptQuota = transcriptBaseShare + 3;

// Parse content pillars from intel brief
const pillarsMatch = intelBriefText.match(/content pillar[s]?[:\s]+([^\n]+(?:\n[-•*][^\n]+)*)/gi);
const contentPillarsRaw = pillarsMatch ? pillarsMatch[0] : 'See Intelligence Brief';

// Check for Miscellaneous pillar
const hasMiscPillar = /miscellaneous/i.test(intelBriefText);

return [{
  json: {
    ...dashboardInfo,
    intel_brief_text: intelBriefText,
    strategy_doc_text: strategyDocText,
    total_posts_per_batch: totalPostsPerBatch,
    linkedin_posts: linkedinPosts,
    x_posts: xPosts,
    transcript_idea_quota: transcriptQuota,
    content_pillars_raw: contentPillarsRaw,
    has_misc_pillar: hasMiscPillar
  }
}];

const allItems = $input.all();
const contextData = $('Extract Context & Calculate Quota').first().json;

// Separate Grain calls from Notion agenda rows
// Grain response has 'recordings' array or array of recording objects
const grainItem = allItems[0]?.json;
const notionItem = allItems[1]?.json;

const grainCalls = (grainItem?.recordings || grainItem?.data || [grainItem]).filter(Boolean);
const notionRows = notionItem?.results || [];

// Sort Grain calls by date ascending
const sortedGrainCalls = grainCalls
  .filter(c => c.started_at || c.created_at || c.date)
  .sort((a, b) => {
    const dateA = new Date(a.started_at || a.created_at || a.date);
    const dateB = new Date(b.started_at || b.created_at || b.date);
    return dateA - dateB;
  });

// Get Notion row dates
const notionDates = notionRows.map(row => ({
  id: row.id,
  title: row.properties?.Name?.title?.[0]?.plain_text || '',
  date: row.properties?.Date?.date?.start || '',
  transcript_url: row.properties?.['Transcript Doc']?.url || row.properties?.['Transcript Link']?.url || ''
}));

// Determine call number for the new call
// Use the max of: Notion row count + 1, or Grain call index + 1 (whichever is more accurate)
const latestGrainCall = sortedGrainCalls[sortedGrainCalls.length - 1];
const callNumber = Math.max(notionRows.length + 1, sortedGrainCalls.length);

return [{
  json: {
    ...contextData,
    latest_grain_call_id: latestGrainCall?.id || latestGrainCall?.recording_id || '',
    latest_grain_call_title: latestGrainCall?.title || latestGrainCall?.name || '',
    latest_grain_call_date: latestGrainCall?.started_at || latestGrainCall?.created_at || '',
    new_call_number: callNumber,
    existing_notion_rows: notionDates,
    action: 'create_new'
  }
}];

const crosscheckData = $('Cross-check Dates & Determine Call #').first().json;
const grainTranscript = $('Fetch Grain Transcript').first().json;
const createdDoc = $('Create Google Doc').first().json;

// Extract transcript text from Grain response
// Grain transcript format: array of segments { speaker, text, timestamp } or plain text
let transcriptText = '';
if (Array.isArray(grainTranscript?.transcript)) {
  transcriptText = grainTranscript.transcript
    .map(seg => `[${seg.timestamp || seg.start || ''}] ${seg.speaker || 'Speaker'}: ${seg.text || seg.content || ''}`)
    .join('\n');
} else if (grainTranscript?.text) {
  transcriptText = grainTranscript.text;
} else if (grainTranscript?.content) {
  transcriptText = grainTranscript.content;
} else {
  transcriptText = JSON.stringify(grainTranscript, null, 2);
}

const docId = createdDoc.documentId;
const docUrl = `https://docs.google.com/document/d/${docId}/edit`;

// Google Docs batchUpdate body — insert text at index 1 (after title)
const batchUpdateBody = {
  requests: [
    {
      insertText: {
        location: { index: 1 },
        text: transcriptText
      }
    }
  ]
};

return [{
  json: {
    ...crosscheckData,
    doc_id: docId,
    doc_url: docUrl,
    transcript_text: transcriptText,
    batch_update_body: batchUpdateBody
  }
}];

const prepData = $('Prepare Transcript for Doc').first().json;
const agendaRow = $('Create Call Agendas Row').first().json;

return [{
  json: {
    ...prepData,
    agenda_row_id: agendaRow.id,
    transcript_doc_url: prepData.doc_url,
    call_title: `Call ${prepData.new_call_number} - ${prepData.client_name} x Digital Leverage`,
    source: 'fresh_fetch'
  }
}];

const contextData = $('Extract Context & Calculate Quota').first().json;
const notionResult = $input.first().json;
const rows = notionResult.results || [];

if (rows.length === 0) {
  throw new Error(`No call agendas found for client: ${contextData.client_name}. Please check the 'Fetch Latest Call Transcript' option or add a call to the Call Agendas database.`);
}

const latestRow = rows[0];
const props = latestRow.properties || {};
const transcriptUrl = props['Transcript Doc']?.url || props['Transcript Link']?.url || '';
const callTitle = props['Name']?.title?.[0]?.plain_text || 'Unknown Call';
const callDate = props['Date']?.date?.start || '';

if (!transcriptUrl) {
  throw new Error(`No transcript doc URL found in the latest Call Agendas row for: ${contextData.client_name}`);
}

return [{
  json: {
    ...contextData,
    agenda_row_id: latestRow.id,
    transcript_doc_url: transcriptUrl,
    call_title: callTitle,
    call_date: callDate,
    source: 'existing'
  }
}];

// After merge, take the first item (whichever branch fired)
const item = $input.first().json;

// If specific call override was flagged, we'll handle that in the next IF node
return [{ json: item }];

const currentData = $('Select Transcript Item').first().json;
const notionResult = $input.first().json;
const rows = notionResult.results || [];

if (rows.length === 0) {
  throw new Error('Specific call not found. Check the call number or date in Notes for AI.');
}

const row = rows[0];
const props = row.properties || {};
const transcriptUrl = props['Transcript Doc']?.url || props['Transcript Link']?.url || '';
const callTitle = props['Name']?.title?.[0]?.plain_text || 'Unknown Call';

if (!transcriptUrl) throw new Error(`No transcript URL for the requested call: ${callTitle}`);

return [{
  json: {
    ...currentData,
    transcript_doc_url: transcriptUrl,
    call_title: callTitle,
    source: 'specific_override'
  }
}];

const contextData = $('Pick Final Transcript').first().json;
const docData = $input.first().json;

// Extract plain text from Google Docs API response
function extractDocText(doc) {
  if (!doc.body || !doc.body.content) return '';
  let text = '';
  for (const element of doc.body.content) {
    if (element.paragraph) {
      for (const el of (element.paragraph.elements || [])) {
        if (el.textRun) text += el.textRun.content || '';
      }
    }
    if (element.table) {
      for (const row of (element.table.tableRows || [])) {
        for (const cell of (row.tableCells || [])) {
          for (const content of (cell.content || [])) {
            if (content.paragraph) {
              for (const el of (content.paragraph.elements || [])) {
                if (el.textRun) text += el.textRun.content || '';
              }
            }
          }
        }
      }
    }
  }
  return text;
}

const transcriptText = extractDocText(docData);

return [{
  json: {
    ...contextData,
    transcript_text: transcriptText
  }
}];

const contextData = $('Extract Transcript Text').first().json;
const formatBankResult = $('Query Format Bank – Pass 1').first().json;

// Parse format bank into a concise reference list
const formatList = (formatBankResult.results || []).map(page => {
  const props = page.properties || {};
  return {
    name: props['Format Name']?.title?.[0]?.plain_text || '',
    description: props['Format Description']?.rich_text?.[0]?.plain_text || '',
    when_to_use: props['When To Use It']?.rich_text?.[0]?.plain_text || '',
    platform: props['Platform']?.select?.name || 'LinkedIn & X/Twitter'
  };
}).filter(f => f.name);

const userPrompt = `You are analyzing a call transcript to extract high-quality social media content ideas for a client.

---
CLIENT: ${contextData.client_name}

INTELLIGENCE BRIEF:
${contextData.intel_brief_text}

CONTENT STRATEGY (posting cadence: ${contextData.total_posts_per_batch} posts/batch — LinkedIn: ${contextData.linkedin_posts}, X/Twitter: ${contextData.x_posts}):
${contextData.strategy_doc_text}

WRITER'S NOTES FOR THIS BATCH:
${contextData.notes_for_ai || 'None'}

CALL TITLE: ${contextData.call_title || 'Most recent call'}

FULL TRANSCRIPT:
${contextData.transcript_text}

---
FORMAT BANK (name | description | when to use | platform):
${formatList.map(f => `• ${f.name} | ${f.description} | ${f.when_to_use} | ${f.platform}`).join('\n')}

---
TARGET: Generate ${contextData.transcript_idea_quota} ideas from this transcript.

Return ONLY a valid JSON array. No preamble, no markdown. Each element:
{
  "topic": "one word, two words, or one line",
  "one_of_one_opinion": "the unique take only this client can have",
  "content_pillar": "exact pillar name from the strategy doc",
  "transcript_source": "direct quote or clear description of the specific moment this came from",
  "format_candidates": ["Format Name 1", "Format Name 2", "Format Name 3"],
  "platform_lean": "LinkedIn" or "X/Twitter" or "Either",
  "notes_for_reviewer": "any flags or questions for the human reviewer, empty string if none"
}`;

return [{
  json: {
    ...contextData,
    format_list: formatList,
    mine_ideas_user_prompt: userPrompt
  }
}];

const contextData = $('Prepare Mine Ideas Context').first().json;
const claudeResponse = $input.first().json;

// Extract content from Claude response
const content = claudeResponse.content?.[0]?.text || claudeResponse.content || '';

// Parse JSON from Claude output
let ideas = [];
try {
  const jsonMatch = content.match(/\[\s*\{[\s\S]*\}\s*\]/);
  ideas = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch (e) {
  throw new Error('Failed to parse ideas from Claude: ' + content.substring(0, 500));
}

if (!Array.isArray(ideas) || ideas.length === 0) {
  throw new Error('Claude returned no ideas. Response: ' + content.substring(0, 500));
}

// Collect all unique format candidates for Pass 2 lookup
const allFormatNames = [...new Set(ideas.flatMap(idea => idea.format_candidates || []))];

return [{
  json: {
    ...contextData,
    raw_ideas: ideas,
    format_names_needed: allFormatNames
  }
}];

const contextData = $('Parse Ideas & Extract Format Names').first().json;
const formatExamples = $('Query Format Bank – Pass 2 (Examples)').first().json;

// Build format examples reference
const examplesMap = {};
(formatExamples.results || []).forEach(page => {
  const props = page.properties || {};
  const name = props['Format Name']?.title?.[0]?.plain_text || '';
  if (name) {
    examplesMap[name] = {
      name,
      description: props['Format Description']?.rich_text?.[0]?.plain_text || '',
      when_to_use: props['When To Use It']?.rich_text?.[0]?.plain_text || '',
      platform: props['Platform']?.select?.name || 'LinkedIn & X/Twitter',
      example_1: props['Example 1']?.rich_text?.[0]?.plain_text || '',
      example_2: props['Example 2']?.rich_text?.[0]?.plain_text || '',
      example_3: props['Example 3']?.rich_text?.[0]?.plain_text || ''
    };
  }
});

const userPrompt = `You are finalizing a list of content ideas by confirming the best format for each idea, assigning platform, and running a quality checklist.\n\nCLIENT: ${contextData.client_name}\nBATCH SIZE: ${contextData.total_posts_per_batch} posts — LinkedIn: ${contextData.linkedin_posts}, X/Twitter: ${contextData.x_posts}\nWRITER\'S NOTES: ${contextData.notes_for_ai || 'None'}\n\nFORMAT EXAMPLES FOR CANDIDATES SELECTED:\n${JSON.stringify(examplesMap, null, 2)}\n\nIDEAS TO FINALIZE:\n${JSON.stringify(contextData.raw_ideas, null, 2)}\n\nFor each idea:\n1. Review the format examples. Confirm whether the leading candidate is the best fit, or upgrade based on the examples\n2. Assign a final platform (LinkedIn or X/Twitter) based on the format\'s platform field and the cadence split above\n3. Run all 5 quality checks — remove ideas that fail and cannot be fixed\n4. Fill in all output fields completely\n\nReturn ONLY a valid JSON array. Each element:\n{\n  \

\n}`;

return [{
  json: {
    ...contextData,
    examples_map: examplesMap,
    finalize_user_prompt: userPrompt
  }
}];

const contextData = $('Prepare Finalize Ideas Context').first().json;
const claudeResponse = $input.first().json;

const content = claudeResponse.content?.[0]?.text || claudeResponse.content || '';

let finalIdeas = [];
try {
  const jsonMatch = content.match(/\[\s*\{[\s\S]*\}\s*\]/);
  finalIdeas = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch (e) {
  throw new Error('Failed to parse final ideas from Claude: ' + content.substring(0, 500));
}

// Filter to only ideas that pass checklist
const passedIdeas = finalIdeas.filter(idea => idea.passes_checklist !== false);

if (passedIdeas.length === 0) {
  throw new Error('No ideas passed the quality checklist. Review the transcript and try again.');
}

// Total passing ideas
const linkedinCount = passedIdeas.filter(i => i.platform === 'LinkedIn').length;
const xCount = passedIdeas.filter(i => i.platform === 'X/Twitter').length;

return [{
  json: {
    ...contextData,
    final_ideas: passedIdeas,
    total_ideas: passedIdeas.length,
    linkedin_idea_count: linkedinCount,
    x_idea_count: xCount
  }
}];

const contextData = $('Parse Final Ideas').first().json;
const batchCountResult = $input.first().json;

const existingBatches = batchCountResult.results || [];
const nextBatchNumber = existingBatches.length + 1;

// Batch name: Batch [#]. [CallSign] x [# Posts]
const batchName = `Batch ${nextBatchNumber}. ${contextData.call_sign} x ${contextData.total_posts_per_batch}`;

return [{
  json: {
    ...contextData,
    batch_number: nextBatchNumber,
    batch_name: batchName
  }
}];

const contextData = $('Build Batch Name').first().json;
const batchPage = $('Create Batch Page').first().json;

const batchPageId = batchPage.id;
const batchPageUrl = batchPage.url || `https://notion.so/${batchPageId.replace(/-/g, '')}`;

// Store batch context in static data so the loop can access it
const staticData = $getWorkflowStaticData('global');
staticData.batchContext = {
  batch_page_id: batchPageId,
  batch_page_url: batchPageUrl,
  batch_name: contextData.batch_name,
  client_name: contextData.client_name,
  call_sign: contextData.call_sign,
  total_posts_per_batch: contextData.total_posts_per_batch,
  call_title: contextData.call_title,
  notes_for_ai: contextData.notes_for_ai
};
staticData.createdRows = [];

// Return one item per idea for the loop
return contextData.final_ideas.map((idea, index) => ({
  json: {
    ...idea,
    batch_page_id: batchPageId,
    batch_page_url: batchPageUrl,
    batch_name: contextData.batch_name,
    client_name: contextData.client_name,
    idea_index: index
  },
  pairedItem: { item: 0 }
}));

const staticData = $getWorkflowStaticData('global');
const ideaData = $('Split Ideas').first().json;
const createdRow = $input.first().json;

if (!staticData.createdRows) staticData.createdRows = [];
staticData.createdRows.push({
  idea: ideaData.idea,
  platform: ideaData.platform,
  format: ideaData.format,
  content_pillar: ideaData.content_pillar,
  notes_for_reviewer: ideaData.notes_for_reviewer,
  notion_row_id: createdRow.id
});

return [{ json: { row_created: true, notion_row_id: createdRow.id } }];

const staticData = $getWorkflowStaticData('global');
const ctx = staticData.batchContext || {};
const rows = staticData.createdRows || [];

// Top 5 ideas for the Slack summary
const topIdeas = rows.slice(0, 5);
const ideaSummary = topIdeas
  .map((r, i) => `${i + 1}. *[${r.platform}]* ${r.idea}`)
  .join('\n');

// Top notes from AI
const topNotes = rows
  .filter(r => r.notes_for_reviewer && r.notes_for_reviewer.trim())
  .slice(0, 3)
  .map((r, i) => `• ${r.notes_for_reviewer}`)
  .join('\n');

const message = `:brain: *New Idea Batch Ready for Review!*\n\n*Client:* ${ctx.client_name}\n*Batch:* ${ctx.batch_name}\n*Source:* Call Transcript — ${ctx.call_title || 'Latest Call'}\n*Total Ideas:* ${rows.length}\n\n*Top Ideas:*\n${ideaSummary}${topNotes ? `\n\n*AI Notes to Review:*\n${topNotes}` : ''}\n\n<${ctx.batch_page_url}|View Batch in Notion>`;

return [{
  json: {
    slack_message: message,
    batch_page_url: ctx.batch_page_url,
    batch_name: ctx.batch_name,
    client_name: ctx.client_name,
    total_ideas: rows.length
  }
}];
